use std :: path :: Path ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Transforms pasted text by wrapping bare file paths in `@[...]` syntax."] # [doc = ""] # [doc = " Called when a bracketed-paste event is received. The pasted content is"] # [doc = " normalised (CRLF to LF) and then checked for file paths. If the entire"] # [doc = " paste (after stripping whitespace/quotes) is a single existing absolute"] # [doc = " path it gets wrapped directly -- this handles paths with spaces. Otherwise"] # [doc = " the text is scanned token-by-token for quoted or unquoted absolute paths."] # [doc = ""] # [doc = " Already-wrapped `@[...]` references and non-existent paths are left"] # [doc = " untouched."] pub fn wrap_pasted_text (pasted : & str) -> String { let normalised = pasted . replace ("\r\n" , "\n") . replace ('\r' , "\n") ; let trimmed = normalised . trim () ; if trimmed . is_empty () { return normalised ; } let unquoted = strip_surrounding_quotes (trimmed) ; if let Some (resolved) = resolve_file_path (unquoted) { let trim_start_len = normalised . trim_start () . len () ; let trim_end_len = normalised . trim_end () . len () ; let leading = normalised . get (.. normalised . len () - trim_start_len) . unwrap_or ("") ; let trailing = normalised . get (trim_end_len ..) . unwrap_or ("") ; return format ! ("{leading}@[{resolved}]{trailing}") ; } wrap_tokens (& normalised) }